def dedupe_sorted(xs):
    """
    Returns a new list with duplicate values removed from the input list xs, preserving the original order.
    Assumes xs is already sorted. Raises TypeError if xs is not a list.
    """
    if not isinstance(xs, list):
        raise TypeError("Argument must be of type list")

    if not xs:
        return []

    result = [xs[0]]
    for i in range(1, len(xs)):
        if xs[i] != result[-1]:
            result.append(xs[i])
    return result
